<?php
namespace App\Controllers;
use Config\Database;
final class VerificationManagementController extends BaseController { public function index(): string { $db=Database::connect();$tab=(string)$this->request->getGet('tab');$tab=in_array($tab,['verifications','requests'],true)?$tab:'verifications';$result=(string)$this->request->getGet('result');$status=(string)$this->request->getGet('status');$date=(string)$this->request->getGet('date');$page=max(1,(int)$this->request->getGet('page'));$query=$tab==='verifications'?$db->table('verification_logs'):$db->table('verification_assistance_requests');if($tab==='verifications'){if(in_array($result,['verified','not_enrolled','student_not_found','invalid_request','unauthorized'],true))$query->where('verification_result',$result);if(preg_match('/\A\d{4}-\d{2}-\d{2}\z/',$date))$query->where('DATE(requested_at)',$date);$query->orderBy('requested_at','DESC')->orderBy('id','DESC');}else{if(in_array($status,['pending','under_review','resolved','rejected'],true))$query->where('status',$status);if(preg_match('/\A\d{4}-\d{2}-\d{2}\z/',$date))$query->where('DATE(created_at)',$date);$query->orderBy('created_at','DESC')->orderBy('id','DESC');}$total=(clone $query)->countAllResults();$rows=$query->limit(25,($page-1)*25)->get()->getResultArray();return view('verification_management/index',['title'=>'Verification Management','tab'=>$tab,'rows'=>$rows,'result'=>$result,'status'=>$status,'date'=>$date,'pager'=>service('pager')->makeLinks($page,25,$total)]);}}
